/// <summary>
/// designed from AVA
/// </summary>
/// <param name="args">args</param>
[PostHandlerFor(formStr(SalesCreateOrder), formMethodStr(SalesCreateOrder, close))]
public static void SalesCreateOrder_Post_close(XppPrePostArgs args)
{
    FormRun         formRun         = args.getThis();
    FormRun         callerFormRun;

    if (formRun.args().caller()   is FormDataSource)
    {
        FormDataSource  callerSalesTableDS =formRun.args().caller();
        callerFormRun  = callerSalesTableDS.formRun();
        FormDataSource      specDiscDS = callerFormRun.dataSource('AVASpecialDiscSalesOrder');

        if (specDiscDS)
        {
            specDiscDS.refresh();
        }

    }
}

