  /// <summary>
  ///    desigend from AVA
  /// </summary>
  /// <param name="sender">sender</param>
  /// <param name="e">e</param>
  [FormControlEventHandler(formControlStr(SalesCreateOrder, AVACreateContactPerson), FormControlEventType::Clicked),
   SuppressBPWarning('BPParameterNotUsed', 'False positive')]
  public static void AVACreateContactPerson_OnClicked(FormControl sender, FormControlEventArgs e)
  {
      FormRun                 formRun =   sender.formRun();     
      FormDataSource          salesTableDS = formRun.dataSource('SalesTable');
      SalesTable              salesTable = salesTableDS.cursor();
      CustTable               locCustTable  = CustTable::find(salesTable.CustAccount);
      boolean                 organisationOK = true;

      DirPartyRecId           custParty =  locCustTable.Party;

      if (custParty == 0)
      {
          organisationOk = checkFailed("@NDX:NXAMissedOrganisation");
      }

      if (organisationOk)
      {
          MenuFunction    menuFunction;
          Args            args = new Args();
          args.record(locCustTable);
          args.caller(formRun);
          args.parmObject(sender);

          menuFunction = new MenuFunction(menuitemDisplayStr(ContactPersonNewQuickCreate), MenuItemType::Display);

          if (menuFunction && menuFunction.checkAccessRights())
          {
              menuFunction.run(args);
          }
      }


  }

/// <summary>
/// AVA
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(SalesCreateOrder, AVADisplayInfoFields), FormControlEventType::Clicked),
         SuppressBPWarning('BPParameterNotUsed', 'False positive')]
public static void AVADisplayInfoFields_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormRun                 formRun =   sender.formRun();
    FormDataSource          salesTableDS = formRun.dataSource(tableStr(SalesTable));
    SalesTable              salesTable = salesTableDS.cursor();
    CustTable               locCustTable  = CustTable::find(salesTable.CustAccount);
    AVASalesInfoFields              custInfoFields;
    KCS_ChainGroupInfoFields        chainGroupInfoFields;
    Dialog                          dialog;
    FormBuildDesign formBuildDesign;
    FormBuildStringControl  SalesInfoTxt, chainInfoTxt, Info1Txt;

    if (!locCustTable)
    {
        Info("@NDX:NXANoCustAccount");
        return;
    }
    custInfoFields = AVASalesInfoFields::find(locCustTable.Party);
    chainGroupInfoFields = KCS_ChainGroupInfoFields::find(locCustTable.CompanyChainId);
    dialog = new Dialog("@NDX:NXAExistingInfo");
    formBuildDesign = dialog.formBuildDesign();
    salesInfotxt = formBuildDesign.addControl(FormControlType::String, "@NDX:NXACustomerInfo");
    SalesInfoTxt.text(custInfoFields.InfoField2);
    SalesInfoTxt.label("@NDX:NXACustomerInfo");
    SalesInfoTxt.displayHeight(10);
    SalesInfoTxt.width(-1, 1);
    SalesInfoTxt.allowEdit(false);
    chainInfoTxt = formBuildDesign.addControl(FormControlType::String, "@NDX:NXAChainInfo");
    chainInfoTxt.label("@NDX:NXAChainInfo");
    chainInfoTxt.text(chainGroupInfoFields.InfoField2);
    chainInfoTxt.width(-1, 1);
    chainInfoTxt.displayHeight(10);
    chainInfoTxt.allowEdit(false);
    Info1Txt = formBuildDesign.addControl(FormControlType::String, "@NDX:NXACustInfo1");
    Info1Txt.label("@NDX:NXACustInfo1");
    Info1Txt.text(custInfoFields.InfoField1);
    Info1Txt.width(-1, 1);
    Info1Txt.displayHeight(10);
    Info1Txt.allowEdit(false);
    dialog.run();


}
